export function installDecisionDetails(events,chains){
 const failures={sect_repair:'旧阵的放电击穿了护符。你受伤退到门外，没有带回完整阵图。',sect_return:'被占院落里的守卫发现了救援。你带伤撤离，没能接出名单上的所有人。',loose_contract:'供货商找人拦住证人，巡查处只收到了不完整的进货单，假药暂未全部封存。',dark_ledger:'顾魇藏起了另一份领用簿，堂主只肯重查药库，没有认可你提出的全部责任。',dark_method:'宁素改过的药仍让经脉发痛，你停药休息，重新检查剂量。',dark_pursuit:'围攻者发现了后门，你带伤撤出，只能继续托药商寻找同伴。',beast_home:'药师遭猎人盘问，约好的交换没能按时完成，你先带病弱幼兽回山。',beast_form:'药师没能查清上次用药的剂量，你先停药，等待身上的疼痛减轻。',beast_war:'守阵者在余震中受伤，阵台没有全部修好，你们退到另一处出口。'};
 for(const chain of chains) for(let step=0;step<chain.stages.length;step++){
  const id=chain.id+'_'+step,node=events[id],hints=CHAIN_DETAILS[chain.id][step];
  events[id]={...node,choices:node.choices.map((choice,i)=>({...choice,hint:hints[i],
   startReply:'你决定'+choice.label+'。'+hints[i].split('。')[0]+'。',
   ...(choice.check&&i===0&&failures[chain.id]?{check:{...choice.check,failText:failures[chain.id]}}:{}),
   // Paperwork does not accidentally turn into a lethal sword fight.
   ...(i===2&&step===1&&['dark_ledger','loose_contract'].includes(chain.id)?{check:undefined}:{}),
  }))};
 }
 events.dark_ledger_0={...events.dark_ledger_0,text:'幽灯堂让你看守药库，交差才能领下一卷功法。管库师兄顾魇掌握钥匙和领药簿，炼气七层，能扣下你的月例。今天账上少了三瓶养脉药，封条却完好。顾魇说整组必须补齐，地牢里刚有一名弟子因缺药被搜魂。新来的阿栾负责搬箱，没有领药权限。'};
 events.dark_method_0={...events.dark_method_0,text:'你练的禁术到了下一层，残卷要求用精血养脉。堂中药师宁素只会配药，不受堂主重视。她提出两条别的路：去黑泽谷捕兽取血，或留在药房试草药配方。顾魇则准许你去地牢取囚犯的血，说这样最快。那些人被抓来后就没再出过地牢，城外已有家人在找他们。',choices:events.dark_method_0.choices.map((c,i)=>({...c,label:i===0?'去黑泽谷采集妖兽血':c.label}))};
 events.dark_ledger_1={...events.dark_ledger_1,choices:events.dark_ledger_1.choices.map((c,i)=>i===2?{...c,reply:'你抄下出库签名，把原册还给顾魇。副本藏在自己的药袋里，尚未被旁人看见。',effects:{flags:{secretLedger:true}},system:{...c.system,concealed:true}}:c)};
 events.dark_method_2={...events.dark_method_2,text:'宁素把试药报告交给药房管事，报告附着你写过的行气笔记。堂主因而得知你改过功法，要求收走全本：他说堂中养了你，这份本事也该归堂中。顾魇先来讨副本，门口已有人登记你借阅的卷册。你还不知道堂主是否肯接受功法的缺陷。'};
 events.root_result={...events.root_result,choices:events.root_result.choices.map(c=>c.id==='dark'?{...c,label:'听取幽灯堂招收弟子的条件',hint:'顾魇能教测灵石不收的禁术，但要先见堂规；现在还没有拜师。',reply:'顾魇带你到药铺，拿出试读卷与堂规，让你先问清条件。',next:'dark_invitation',system:{inquiry:'demonic'},effects:{flags:{darkFragment:true}}}:c)};
}
